[CmdletBinding()]param([string]$ManifestPath,[Parameter(Mandatory=$true)][string]$TarballPath,[Parameter(Mandatory=$true)][string]$OutputPath)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
if([string]::IsNullOrWhiteSpace($ManifestPath)){$ManifestPath=Join-Path $PSScriptRoot '..\manifest\product-manifest.json'}
function Out($s,$c,$x,$n=2){[pscustomobject]@{schemaVersion='1';status=$s;code=$c;checkedAtUtc=[DateTime]::UtcNow.ToString('o');checks=$x}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $OutputPath -Encoding UTF8;if($s -ne 'PASS'){exit $n}}
try{if(!(Test-Path -LiteralPath $TarballPath -PathType Leaf)){Out 'FAIL' 'ARTIFACT_MISSING' @{} 3};if(!(Get-Command tar.exe -ErrorAction SilentlyContinue)){Out 'FAIL' 'TAR_TOOL_MISSING' @{} 4};& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'Test-Governance.ps1') -ManifestPath $ManifestPath|Out-Null;if($LASTEXITCODE -ne 0){Out 'FAIL' 'UNTRUSTED_MANIFEST' @{} 3};$m=Get-Content $ManifestPath -Raw|ConvertFrom-Json;$sha=(Get-FileHash $TarballPath -Algorithm SHA256).Hash.ToLowerInvariant();$fs=[IO.File]::OpenRead($TarballPath);try{$sri='sha512-'+[Convert]::ToBase64String([Security.Cryptography.SHA512]::Create().ComputeHash($fs))}finally{$fs.Dispose()};$entries=& tar.exe -tzf $TarballPath;$safe=($LASTEXITCODE -eq 0 -and @($entries|?{$_ -match '(^/|^\\|^[A-Za-z]:)' -or (($_ -split '[\\/]') -contains '..')}).Count -eq 0);$c=@{sha256=($sha -eq $m.upstream.sha256);integrity=($sri -eq $m.upstream.integrity);safeTarPaths=$safe};Out $(if($c.Values -notcontains $false){'PASS'}else{'FAIL'}) 'ARTIFACT_VERIFIED' $c}catch{Out 'FAIL' 'ARTIFACT_INPUT_OR_HASH_ERROR' @{} 3}
